     */
    @Throws(DspiException::class)
    fun setCrossfeedOutputs(pairMask: Int)

    /**
     * Volume leveller on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerEnabled(enabled: Boolean)

    /**
     * Leveller amount in percent, clamped to 0..100 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerAmount(pct: Float)

    /**
     * 0 slow, 1 medium, 2 fast.
     *
     * Errors: [`DspiError::InvalidArgument`] for another speed; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerSpeed(speed: Int)

    /**
     * Leveller maximum gain in dB, clamped to 0..35 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerMaxGain(db: Float)

    /**
     * Leveller look-ahead on (`true`) or off.
     *
     * Errors: the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerLookahead(enabled: Boolean)

    /**
     * Leveller gate threshold in dB, clamped to −96..0 as the firmware does.
     *
     * Errors: [`DspiError::InvalidArgument`] for a NaN; the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerGate(db: Float)

    /**
     * Leveller detector and apply masks (bit k: output k).
     *
     * Errors: [`DspiError::Unsupported`] on firmware without the masks; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setLevellerMasks(detector: Int, apply: Int)

    /**
     * Input source: 0 USB, 1 S/PDIF, 2 I2S, 3 ADAT, 4..6 S/PDIF inputs 2..4,
     * 7 the audio link (WP SW1). The firmware switches on its main loop and
     * ignores a source that is not selectable (a disabled S/PDIF input); its
     * notification at the switch, or a re-read, corrects the mirror.
     *
     * Errors: [`DspiError::InvalidArgument`] above 7;
     * [`DspiError::Unsupported`], with no traffic, for 7 on a unit without
     * the link input (`alink_info`'s `alink_input`); the connection and
     * transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setInputSource(source: Int)

    /**
     * One matrix crosspoint: route `input` to `output`, with a gain in dB
     * (quantized to 0.1 dB) and polarity.
     *
     * Errors: [`DspiError::InvalidArgument`] for an input or output out of
     * range or a non-finite gain; the connection and transfer errors of
     * every setter.
     */
    @Throws(DspiException::class)
    fun setMatrixRoute(input: Int, output: Int, enabled: Boolean, gain: Float, invert: Boolean)

    /**
     * Enable or disable an output. Returns the resulting state, read back
     * from the device: the firmware silently refuses an enable that would
     * collide on Core 1 (PDM against the EQ-worker outputs). An enable is
     * checked first (`REQ_GET_CORE1_CONFLICT`) and not sent when it would
     * collide. The Core 1 mode is re-read afterwards when the device
     * answers it.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range; the
     * connection and transfer errors of every setter. A failed read-back is
     * not an error: the requested state (or, after a refused enable, the
     * previous one) is assumed, as the old core did.
     */
    @Throws(DspiException::class)
    fun setOutputEnable(output: Int, enabled: Boolean): Boolean

    /**
     * Output gain in dB, clamped to −60..+20 and quantized to 0.1 dB.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range or
     * a NaN; the connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setOutputGain(output: Int, db: Float)

    /**
     * Mute (`true`) or unmute one output.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setOutputMute(output: Int, muted: Boolean)

    /**
     * Output delay in ms, quantized to 0.0001 ms; below 0 it is 0. It is
     * also the delay of the output's wire channel.
     *
     * Errors: [`DspiError::InvalidArgument`] for an output out of range, a
     * NaN, or a delay above the platform's [`DspiCore::max_delay_ms`] (the
     * message names it; nothing is sent); the connection and transfer
     * errors of every setter.
     */
    @Throws(DspiException::class)
    fun setOutputDelay(output: Int, ms: Float)

    /**
     * Name of wire channel `ch`, cut to 31 bytes on a character boundary
     * (the firmware keeps 31 and a NUL).
     *
     * Errors: [`DspiError::InvalidArgument`] for a channel out of range; the
     * connection and transfer errors of every setter.
     */
    @Throws(DspiException::class)
    fun setChannelName(ch: Int, name: String)

    /**
     * Reads the name of wire channel `ch` from the device
     * (`REQ_GET_CHANNEL_NAME`) and keeps it in the mirror. Works on a
     * read-only connection too (its image is then left alone).
     *
     * Errors: [`DspiError::Disconnected`] with no device;
     * [`DspiError::InvalidArgument`] for a channel out of range; the
     * transfer's error.
     */
    @Throws(DspiException::class)
    fun getChannelName(ch: Int): String

    /**
     * Set one psychoacoustic-bass parameter. `param`: `PSYBASS_PARAM_*`
     * (cutoff Hz 30..300, harmonics dB -24..12, drive dB 0..18, character %
     * 0..100, original dB -60..0); the value is clamped to that range.
     *
     * Errors: `InvalidArgument` (unknown `param`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no psychoacoustic bass), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setPsybassParam(param: Int, value: Float)

    /**
     * Which outputs psychoacoustic bass processes: bit k = output k.
     *
     * Errors: `Disconnected`, `ReadOnly`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun setPsybassMask(mask: Int)

    /**
     * Turn psychoacoustic bass on or off.
     *
     * Errors: `Disconnected`, `ReadOnly`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun setPsybassEnabled(enabled: Boolean)

    /**
     * Set one output-limiter parameter of `output` (0-based), or of every
     * output when `output` is `LIMITER_ALL_OUTPUTS` (0xFF). `param`:
     * `LIMITER_PARAM_*` (enabled: non-zero is on; threshold dB -30..0;
     * release ms 10..1000; link group 0..4, 0 = unlinked), clamped as the
     * firmware does. The mirror follows the firmware's link groups: a write
     * to one member moves the whole group, joining a group adopts its
     * settings, and a group set on every output gangs each group to its
     * lowest member.
     *
     * Errors: `InvalidArgument` (unknown `param`, NaN, an output past the
     * device's), `Disconnected`, `ReadOnly`, `Unsupported` (no limiter),
     * `Transfer`.
     */
    @Throws(DspiException::class)
    fun setLimiterParam(output: Int, param: Int, value: Float)

    /**
     * Gain reduction per output in dB (positive while limiting, 120 = the
     * display floor), [`MAX_OUTPUTS`] entries; outputs the device does not
     * have read 0. Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Unsupported` (no limiter), `Transfer`
     * (including a short reply).
     */
    @Throws(DspiException::class)
    fun fetchLimiterMeter(): List<Float>

    /**
     * Protect every output (PRO1 S2): every output's limiter on, each
     * stereo pair of outputs linked (outputs 2p and 2p+1 in link group p+1,
     * for the first four pairs below the PDM sub, which is the last output;
     * every other output unlinked), and every limiter at `ceiling_dbfs`.
     * -1 dBFS is the usual ceiling; the value is clamped to the limiter's
     * -30..0 dB as [`DspiCore::set_limiter_param`] clamps it. The release is
     * not changed (a pair adopts its lower output's). A write that would
     * change nothing is not sent.
     *
     * Undo: one undo group labelled "Protect all outputs". Switching a
     * limiter is audible (`limit.on`'s hazard in the registry), so no undo
     * switches one back off: the enable is written first and stands apart,
     * and one undo puts back the link groups, the thresholds and the
     * releases, leaving the limiters on.
     *
     * The ceiling is checked before anything is sent. A failure part way
     * leaves what was written.
     *
     * Under a limits profile (WP P1CFIX, F5) an output whose profile ceiling
     * is lower takes that ceiling instead (a linked pair, its lower one), and
     * each such output is reported in [`DspiCore::limits_status`]'s
     * `last_held` ("limit.threshold[3] -1 → -3 dB"). Every write is judged
     * against the profile before the first is sent, so the call is never
     * refused half-way (when the pairs change, every threshold goes to the
     * lowest target first, then the pairs are linked, then each output or
     * pair is set to its own).
     *
     * Errors: `InvalidArgument` (a NaN ceiling), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no limiter), `Transfer`; `LimitExceeded`,
     * with nothing sent, should the profile still refuse one of the writes.
     */
    @Throws(DspiException::class)
    fun protectAllOutputs(ceilingDbfs: Float)

    /**
     * The outputs (0-based, ascending) that are on, have a gain above
     * `threshold_db` and no limiter on: PRO1 S2's warning "an output above
     * -10 dB gain has no limiter" (pass -10). Read from the mirror, nothing
     * sent; works on a read-only connection. Empty with no device, on
     * firmware without the output limiter, and for a NaN threshold.
     */
    fun outputsWithoutLimiter(thresholdDb: Float): List<Int>

    /**
     * Set upmixer parameter `id` (`UPMIX_PARAM_*`); RP2350 only. The value
     * is clamped to the firmware's range; the enable and the modes are
     * rounded (an out-of-range centre mode becomes adaptive, as the
     * firmware does), the presence goes in 0.5 dB steps.
     *
     * Errors: `InvalidArgument` (unknown `id`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (RP2040), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setUpmixParam(id: Int, value: Float)

    /**
     * The upmixer's live state: active, why it is parked, correlation and
     * balance (-1..1, 0..1), and the centre and surround gains (0..1). All
     * zero on an RP2040. Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Transfer` (including a reply under 12
     * bytes).
     */
    @Throws(DspiException::class)
    fun fetchUpmixStatus(): UpmixStatus

    /**
     * Set subharmonic-synth parameter `id` (`SUBHARM_PARAM_*`), clamped to
     * its range; the flags, the mask and the selectivity mode are rounded.
     *
     * Errors: `InvalidArgument` (unknown `id`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no subharmonic synth), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setSubharmParam(id: Int, value: Float)

    /**
     * Mute the program on the subharm outputs so the synthesized sub is
     * heard alone. Monitoring only: never saved, not in the bulk image.
     *
     * Errors: `Disconnected`, `ReadOnly`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun setSubharmSolo(solo: Boolean)

    /**
     * How far the current subharm settings can push the signal above its
     * input, dB (computed by the device). Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun fetchSubharmHeadroom(): Float

    /**
     * Decaying peak of the synthesized sub per output, 0..1,
     * [`MAX_OUTPUTS`] entries; outputs the device does not have read 0.
     * Works on a read-only connection.
     *
     * Errors: `Disconnected`, `Unsupported`, `Transfer`.
     */
    @Throws(DspiException::class)
    fun fetchSubharmMeter(): List<Float>

    /**
     * Set tube-preamp parameter `idx` (`TUBE_PARAM_*`), clamped to its
     * range; the flags, the mask, the type and the rectifier are rounded.
     * The mirror follows the firmware: choosing a type 1..16 loads its
     * bias, asymmetry, hardness and sag; changing one of those four drops
     * the type to Custom (0).
     *
     * Errors: `InvalidArgument` (unknown `idx`, NaN), `Disconnected`,
     * `ReadOnly`, `Unsupported` (no tube preamp), `Transfer`.
     */
    @Throws(DspiException::class)
    fun setTubeParam(idx: Int, value: Float)

    /**
     * Flash `image` into the boot ROM of `target` (one of
     * [`picoboot_devices`]) over PICOBOOT, with no drive mounted (module
     * docs). `board` is the record [`DspiCore::firmware_guard_board`] read
     * before the board entered BOOTSEL; the guard must say clear for it with
     * nothing typed, so an image that would ask a person anything is
     * refused. Takes a [`ConfirmOp::FirmwareFlash`] token as
     * [`DspiCore::flash_confirmed`] does (mint it once the board is in
     * BOOTSEL; it works with no device open), and the installer lock holds.
     * Blocks for up to 60 s.
     *
     * `Ok` means every sector was written and read back identical and the
     * reboot was acknowledged; the caller confirms by the DSPi coming back
     * with the image's version. On an error after the first erase the board
     * stays in BOOTSEL (nothing is retried).
     *
     * Errors: [`DspiError::ConfirmationRequired`] without a good token;
     * [`DspiError::FirmwareGuardBlocked`] or [`DspiError::InvalidArgument`]
     * for an image the guard does not clear, of another chip, or not
     * firmware; [`DspiError::Unsupported`] where the bus cannot be reached;
     * [`DspiError::Transfer`] naming the step for anything the transfer or
     * the ROM did. In every error before the first command nothing was sent.
     */
    @Throws(DspiException::class)
    fun picobootFlashConfirmed(image: List<Int>, target: BootDevice, board: FirmwareGuardBoard, token: String?): FlashReport

    /**
     * The pin map (WP CG-SWS-b): the platform's valid GPIOs, each function
     * with its pin, whether it holds it and the pins it may move to, and
     * who holds every held GPIO. From the mirror and the last
     * control-surface read: no device I/O. Empty without a device.
     */
    fun pinMap(): PinMap

    /**
     * Whether `function` may move to `pin`: `None` when it may, else why
     * not (with the status the firmware would answer and, when another
     * function holds it, which). From the mirror: no device I/O. The pin
     * setters run this check before they send.
     */
    fun pinCheck(function: PinFunction, pin: Int): PinRefusal?

    /**
     * The function holding `pin`, not counting `excluding` (a picker passes
     * its own function), or `None` when it is free. From the mirror.
     */
    fun pinHolder(pin: Int, excluding: PinFunction?): PinHolder?

    /**
     * Save the live state to `slot` (0..10) and wait until the device has
     * written it (it names the slot active). Runs under the device lock.
     * The slot becomes the active one and the live state its baseline.
     *
     * Without that confirmation the mirror only takes the directory as the
     * device reports it, the baseline stays, and the call fails.
     *
     * Errors: [`DspiError::Refused`] with `PRESET_ERR_INVALID_SLOT` for a
     * slot past the last (nothing is sent) or with the device's `PRESET_*`
     * status; [`DspiError::Transfer`] when the save was not confirmed;
     * [`DspiError::Locked`] / [`DspiError::Denied`] (Link);
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`].
     *
     * Takes a confirmation token ([`crate::confirm`], WP P1TK; required since
     * WP P1TZ): [`DspiError::ConfirmationRequired`], with nothing sent,
     * without a good one. There is no form without a token.
     */
    @Throws(DspiException::class)
    fun savePresetConfirmed(slot: Int, token: String?)

    /**
     * Load preset `slot`, wait until the device runs it, then read the
     * image and the directory again; the loaded state becomes the baseline.
     * Runs under the device lock.
     *
     * The active slot is the directory's after the re-read. When the
     * directory cannot be read, it is `slot` if the device confirmed the
     * load, and stays as it was otherwise. A load that is never confirmed
     * (an empty slot changes nothing) still re-reads and succeeds.
     *
     * Errors: as [`DspiCore::save_preset_confirmed`], and the re-read's.
     */
    @Throws(DspiException::class)
    fun loadPreset(slot: Int)

    /**
     * Copy the live state to `dest` and save it to `source` again, so
     * `source` stays the active preset (the Mac console's "Copy to"). Each
     * save waits for the device; one device lock covers both.
     *
     * If the save to `dest` is not confirmed, nothing more is sent and the
     * baseline stays. After the second save, the live state is the
     * baseline.
     *
     * Errors: the first failing save's (`Refused` with its `PRESET_*`
     * status); [`DspiError::Transfer`] when `dest`'s save was not
     * confirmed; otherwise as [`DspiCore::save_preset_confirmed`].
     *
     * Takes a confirmation token ([`crate::confirm`], WP P1TK; required since
     * WP P1TZ): [`DspiError::ConfirmationRequired`], with nothing sent,
     * without a good one. There is no form without a token.
     */
    @Throws(DspiException::class)
    fun copyPresetConfirmed(source: Int, dest: Int, token: String?)

    /**
     * Delete preset `slot` and wait until the directory no longer holds
     * it; its name goes with it. Runs under the device lock.
     *
     * Deleting the active slot makes the device load its factory defaults:
     * the image is read again and becomes the baseline. A deletion that is
     * never confirmed leaves the slot and its name in the mirror and fails.
     *
     * Errors: as [`DspiCore::save_preset_confirmed`].
     *
     * Takes a confirmation token ([`crate::confirm`], WP P1TK; required since
     * WP P1TZ): [`DspiError::ConfirmationRequired`], with nothing sent,
     * without a good one. There is no form without a token.
     */
    @Throws(DspiException::class)
    fun deletePresetConfirmed(slot: Int, token: String?)

    /**
     * Name preset `slot`: at most 31 bytes of `name` (cut at a character
     * boundary), sent NUL-terminated. The mirror takes the name as sent.
     *
     * Errors: `Refused` with `PRESET_ERR_INVALID_SLOT` for a slot past the
     * last (nothing is sent); [`DspiError::ReadOnly`];
     * [`DspiError::Disconnected`]; a transfer error.
     */
    @Throws(DspiException::class)
    fun setPresetName(slot: Int, name: String)

    /**
     * Read preset `slot`'s name from the device (also into the mirror). An
     * empty slot has no name: the device stalls, and that is the error.
     *
     * Errors: `Refused` with `PRESET_ERR_INVALID_SLOT` for a slot past the
     * last (nothing is sent); [`DspiError::Disconnected`]; a transfer error.
     */
    @Throws(DspiException::class)
    fun getPresetName(slot: Int): String

    /**
     * Read the preset directory (also into the mirror: occupied slots,
     * startup mode, default and active slot, both persistence modes).
     *
     * Errors: [`DspiError::Disconnected`]; a transfer error or a short reply.
     */
    @Throws(DspiException::class)
    fun getPresetDirectory(): PresetDirectory

    /**
     * What the device loads at boot: `mode` 0 (`PRESET_STARTUP_SPECIFIED`)
     * loads `default_slot`, 1 (`PRESET_STARTUP_LAST_ACTIVE`) the slot last
     * active. The mirror takes both.
     *
     * Errors: [`DspiError::InvalidArgument`] for another mode or a slot
     * past the last (nothing is sent); [`DspiError::ReadOnly`];
     * [`DspiError::Disconnected`]; a transfer error.
     */
    @Throws(DspiException::class)
    fun setPresetStartup(mode: Int, defaultSlot: Int)

    /**
     * Save the live state to the active slot (`REQ_SAVE_PARAMS`), under the
     * device lock; the live state becomes the baseline.
     *
     * Errors: `Refused` with the device's `FLASH_*` status;
     * [`DspiError::Locked`] / [`DspiError::Denied`] (Link);
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`]; a transfer
     * error.
     *
     * Takes a confirmation token ([`crate::confirm`], WP P1TK; required since
     * WP P1TZ): [`DspiError::ConfirmationRequired`], with nothing sent,
     * without a good one. There is no form without a token.
     */
    @Throws(DspiException::class)
    fun saveParamsConfirmed(token: String?)

    /**
     * Revert to saved: load the active slot again ([`DspiCore::load_preset`],
     * the device's deferred load, safe on every input).
     *
     * Errors: as `load_preset`, but a refusal carries a `FLASH_*` code:
     * `FLASH_ERR_CRC` for a slot that failed its check, `FLASH_ERR_WRITE`
     * for any other.
     */
    @Throws(DspiException::class)
    fun loadParams()

    /**
     * Restore the factory defaults on the live state (stored presets stay),
     * give the device [`FACTORY_RESET_SETTLE`] to apply them (it defers the
     * reset to its main loop), then read everything again as
     * [`DspiCore::fetch_all`] does; the result is the baseline. Runs under the
     * device lock; the core lock is not held while it waits.
     *
     * Errors: `Refused` with the device's `FLASH_*` status;
     * [`DspiError::Locked`] / [`DspiError::Denied`] (Link);
     * [`DspiError::ReadOnly`]; [`DspiError::Disconnected`]; a transfer
     * error, of the reset or the re-read.
     *
     * Takes a confirmation token ([`crate::confirm`], WP P1TK; required since
     * WP P1TZ): [`DspiError::ConfirmationRequired`], with nothing sent,
     * without a good one. There is no form without a token.
     */
    @Throws(DspiException::class)
    fun factoryResetConfirmed(token: String?)

    /**
     * Take the live state as what the active preset holds: from now on
     * [`DspiCore::preset_changes`] lists what differs from it. The core
     * does this itself after a connect, a load, a save, a revert and a
     * factory reset. Without a device, or without an image in this build's
     * format, there is no baseline.
     */
    fun captureBaseline()

    /**
     * Whether the live state differs from the active preset: exactly when
     * [`DspiCore::preset_changes`] has something to say. No I/O.
     */
    fun presetDirty(): Boolean

    /**
     * What differs from the active preset, one sentence each, in the Mac
     * console's words and order. Empty without a device or a baseline. No
     * I/O: input source titles come from the names the core keeps.
     */
    fun presetChanges(): List<String>

    /**
     * Hold the device lock across a flow of several calls (a restore, a
     * firmware install), for at most `timeout_ms` (capped at 60 000), until
     * [`DspiCore::device_lock_release`]: another DSPi Link session's
     * commands answer locked meanwhile. The core's own flows nest inside it.
     * Blocking over Link: call it off the UI thread.
     *
     * An acquire while a lock is held asks nothing more; one held by an IR
     * learn window or the bootloader restart becomes the caller's. Elsewhere
     * than over Link it succeeds without asking anyone.
     *
     * Errors: [`DspiError::InvalidArgument`] for a zero timeout;
     * [`DspiError::Disconnected`]; [`DspiError::Locked`] while another
     * session holds it; [`DspiError::Denied`].
     */
    @Throws(DspiException::class)
    fun deviceLockAcquire(reason: String, timeoutMs: Long)

    /**
     * Give back the lock [`DspiCore::device_lock_acquire`] took, and only
     * that one: an IR learn window or the bootloader restart ends on its own
     * terms. Idempotent; never blocks.
     */
    fun deviceLockRelease()

    /**
     * One IN transfer: `opcode`, `value` as `wValue`, at most `len` bytes
     * back. The reply is returned as the device sent it, so it may be
     * shorter than `len`, and a status byte in it is not interpreted.
     *
     * An opcode that is not a plain read (`REQ_PRESET_LOAD`,
     * `REQ_RTA_CONTROL`, ...) is a write-as-read and is treated as a write.
     * A plain read is any `*_GET_*` opcode, `REQ_EXTENSION`, `REQ_LIMITER`,
     * `REQ_OUTPUT_LATENCY`, and the §1.2 exceptions `REQ_CLEAR_CLIPS` and
     * `REQ_RESET_BUFFER_STATS` (`REQ_ENTER_BOOTLOADER`, the third, is refused
     * here since WP P1TZF: it takes a token, through
     * `enter_bootloader_confirmed`).
     *
     * The mirror does not change here. A device change reaches it through
     * the notification, like anyone else's. Over DSPi Link the
     * `BULK_INVALIDATED` of a command of ours counts as our own echo and
     * does not re-read, so after a raw command that replaces many settings
     * (a preset load) call [`refresh_params`](Self::refresh_params) there.
     *
     * Blocks for the transfer with the core's lock held: call it off the UI
     * thread. `REQ_GET_ALL_PARAMS` for a whole image is the slow case.
     *
     * Errors: [`DspiError::InvalidArgument`] for `REQ_SET_ALL_PARAMS` and
     * the chunk opcodes, and for an opcode behind a confirmation token
     * ([`raw_gated_call`]: preset save and delete, parameter and output
     * configuration save, factory reset, the bootloader), naming the
     * `_confirmed` call to use (nothing is sent; WP P1TZF);
     * [`DspiError::Disconnected`];
     * [`DspiError::ReadOnly`] for a write-as-read on a read-only connection
     * (nothing is sent); [`DspiError::Refused`] with status 0 when the
     * device stalls; [`DspiError::Denied`], [`DspiError::Locked`] or
     * [`DspiError::Transfer`] from the link.
     */
    @Throws(DspiException::class)
    fun rawGet(opcode: Int, value: Int, len: Int): List<Int>

    /**
     * One OUT transfer: `opcode`, `value` as `wValue`, `data` as the
     * payload. Success means the device took the transfer, not that it
     * applied the value; the firmware ignores some invalid ones.
     *
     * The mirror follows as for [`raw_get`](Self::raw_get). Blocks for the
     * transfer with the core's lock held: call it off the UI thread.
     *
     * Errors: [`DspiError::InvalidArgument`] for `REQ_SET_ALL_PARAMS`, the
     * chunk opcodes, an opcode behind a confirmation token ([`raw_gated_call`],
     * as for `raw_get`), an `EXT_CORE_VREG` request, or more than 65535
     * bytes of `data` (nothing is sent);
     * [`DspiError::Disconnected`]; [`DspiError::ReadOnly`] on a read-only
     * connection (nothing is sent); [`DspiError::Refused`] with status 0
     * when the device stalls; [`DspiError::Denied`], [`DspiError::Locked`]
     * or [`DspiError::Transfer`] from the link.
     */
    @Throws(DspiException::class)
    fun rawSet(opcode: Int, value: Int, data: List<Int>)

    /**
     * Start or stop the notification tap. While on, every notification
     * [`process_notifications`](Self::process_notifications) drains is also
     * kept for [`notify_tap_drain`](Self::notify_tap_drain), in the order
     * the mirror applied them. Off by default; turning it off forgets what
     * it held. Never fails.
     */
    fun notifyTapSet(enabled: Boolean)

    /**
     * The notifications kept since the last drain, oldest first. The tap
     * keeps the last 512; when older ones were dropped, the oldest returned
     * has `lost` set. Empty while the tap is off. Never fails.
     */
    fun notifyTapDrain(): List<RawNotification>

    /**
     * The open connection's generation: unique per connection and never
     * reused while the process runs, so it changes on every reopen and on
     * a Link re-bind. 0 when nothing is open.
     */
    fun connectionGeneration(): Long

    /**
     * Turn the client read-only mode on or off (module docs): while on,
     * every write is refused with [`DspiError::ReadOnly`] before anything is
     * sent, and reads, notifications, the meters and the analyser go on. It
     * applies to every device this core opens until turned off. A client-side
     * diagnostic, not a security boundary. Waits for a call in flight.
     *
     * Turning it on is refused while a guarded apply waits for Keep or
     * Revert (its revert would be refused too, leaving the device on the
     * trial): [`DspiError::InvalidArgument`] with [`GUARD_PENDING`]'s words,
     * the `read_only.guard_pending` row ([`DspiCore::notice_for_error`]),
     * nothing changed. Keep or revert first. Turning it off always works.
     */
    @Throws(DspiException::class)
    fun setClientReadOnly(on: Boolean)

    /**
     * Whether the client read-only mode is on.
     */
    fun clientReadOnly(): Boolean

    /**
     * How many writes the client read-only mode has refused on this core.
     */
    fun clientReadOnlyRefusals(): Long

    /**
     * What to tell the user about `error`, as [`notice_for`] does, but in
     * this core's context: [`DspiError::ReadOnly`] while the client
     * read-only mode is on is the `read_only.client` row.
     */
    fun noticeForError(error: DspiException): Notice

    /**
     * Register (Some) or clear (None) the analyser wake-up listener. Once it
     * returns after None, no call is in progress (on another thread).
     * Replacing (Some -> Some) does not wait, and the old listener may then
     * be released on the RTA thread when its running call ends.
     *
     * The listener is called on the RTA worker thread (and once, for the
     * reset, on the thread that closes or replaces the device) without the
     * core lock held; it may read the core (`rta_get_snapshot`,
     * `get_state`) but must not block.
     */
    fun rtaSetListener(listener: RtaListener?)

    /**
     * Probe the open device's analyser and start polling it, on a worker
     * thread. Only on compatible firmware (a writable connection, PLAN
     * §1.5); a no-op without a device, on a read-only connection, or while
     * a worker was already started for this connection. The worker reads
     * the caps first (`rta_get_caps().supported` stays false on firmware
     * without an analyser) and ends on disconnect, on close and on reopen;
     * call this again after each connect.
     *
     * The worker holds a weak reference to the core for its per-poll lock.
     * Never fails: a worker thread that cannot be spawned is logged and the
     * analyser stays unsupported.
     */
    fun rtaStart()

    /**
     * What to analyse; mask 0 releases the analyser (the worker stops it
     * on the device). Kept across reconnects. Channel bits beyond the tap's
     * width are ignored; an `fft_order` of 0 means the device's default,
     * and one outside the device's range is clamped into it. Wakes the
     * worker at once.
     *
     * A request that changes what this console asks for takes the analyser
     * back from a console being followed ([`Self::rta_get_ownership`]).
     * Releasing it (mask 0) and asking for the same thing again does not.
     *
     * Mask 0 with `watching` set (WP CG30): a view shows the analyser with
     * no channel chosen. It asks for nothing of its own, so while driving
     * the analyser is released as with mask 0; while following, the
     * device's configuration is still polled and in the snapshot.
     */
    fun rtaSetRequest(request: RtaRequest)

    /**
     * The device's analyser as the worker probed it: `supported` false
     * until then, and on firmware without one. `centres` has
     * `RTA_MAX_BANDS` entries, the first `max_bands` in Hz, the rest 0.
     */
    fun rtaGetCaps(): RtaCapsInfo

    /**
     * The latest picture and telemetry. `version` changes only when what is
     * drawn changed, `telemetry_version` when the status line did. Levels
     * are dBFS; a silent channel reads `RTA_FLOOR_DB`.
     */
    fun rtaGetSnapshot(): RtaSnapshot

    /**
     * Whether this console drives the analyser or follows another one's
     * configuration. While following, the snapshot shows the device's tap
     * and channels rather than the request's. The [`RtaListener`] is woken
     * when this changes.
     */
    fun rtaGetOwnership(): RtaOwnership

    /**
     * Stop following and push this console's own request on the next poll.
     * Wakes the worker at once; does nothing while already driving.
     */
    fun rtaTakeControl()

    /**
     * The open device's state as a snapshot document (`.dspipreset` text,
     * `meta.kind = "snapshot"`), not filed: for the web, which keeps
     * snapshots as downloads, and for a client's own store. `name` and
     * `note` (any Unicode; cut to 200 and 4000 characters) go in with it.
     * Reads the settings outside the image (the control surfaces' whole
     * configuration among them); the image is the mirror.
     *
     * Errors: [`DspiError::Disconnected`]; [`DspiError::Transfer`] before
     * the device's settings were read, or for a failed read;
     * [`DspiError::Unsupported`] for firmware whose image this build cannot
     * map.
     */
    @Throws(DspiException::class)
    fun snapshotCaptureDocument(name: String, note: String): String

    /**
     * Recall a snapshot document's text (see
     * [`DspiCore::snapshot_recall`]): for the web and for a document the
     * client keeps itself. Only a snapshot (`meta.kind = "snapshot"` with a
     * `snapshot` block): any other document is refused with
     * [`DspiError::InvalidArgument`] ("not a snapshot — import it instead"),
     * nothing sent; it goes through `config_import` and its token.
     */
    @Throws(DspiException::class)
    fun snapshotRecallDocument(text: String): SnapshotRecall

    /**
     * Keep snapshots in files under `dir`, the client's own data folder
     * (created if missing): one folder per device serial, one document per
     * snapshot and an index. "" forgets the folder.
     *
     * Errors: [`DspiError::Io`] when the folder cannot be created;
     * [`DspiError::Unsupported`] on the web (no files there).
     */
    @Throws(DspiException::class)
    fun snapshotSetDir(dir: String)

    /**
     * Capture the open device as a new snapshot in the store (see
     * [`DspiCore::snapshot_capture_document`]). Errors as there, and
     * [`DspiError::Io`] with no folder named or a failed write.
     */
    @Throws(DspiException::class)
    fun snapshotCapture(name: String, note: String): SnapshotInfo

    /**
     * The snapshots of device `serial` ("" the open device), oldest first.
     * Never fails: no folder, no device or no snapshots is an empty list, and
     * a damaged index is rebuilt from the documents.
     */
    fun snapshotList(serial: String): List<SnapshotInfo>

    /**
     * Recall snapshot `id` on the open device: the settings outside the
     * image that differ (device and source names, output latency, control
     * surfaces), then the image as one bulk write, under the device lock.
     * The undo history before it ends; the event log records a recall with
     * its changes. Live, not stored in a preset slot. Never guarded and
     * never queued: on a lost connection it stops where it is.
     *
     * Errors: [`DspiError::InvalidArgument`] for an unknown id, a document
     * that is not a snapshot, a snapshot of another platform or channel
     * count, or an image of another wire format this build cannot convert
     * (nothing is sent);
     * [`DspiError::Disconnected`], [`DspiError::ReadOnly`],
     * [`DspiError::Locked`] and the transfer errors of a bulk write;
     * [`DspiError::Io`] for an unreadable store. When the image fails after
     * settings outside it were written, the error's words (and a Recall
     * event) say what was written and what was not; a hub's refusal of the
     * image then comes as [`DspiError::Link`] with code `locked` or
     * `denied`.
     */
    @Throws(DspiException::class)
    fun snapshotRecall(id: String): SnapshotRecall

    /**
     * Rename snapshot `id`; any Unicode, cut to 200 characters.
     * Errors: [`DspiError::InvalidArgument`] for an unknown id;
     * [`DspiError::Io`].
     */
    @Throws(DspiException::class)
    fun snapshotRename(id: String, name: String): SnapshotInfo

    /**
     * Set snapshot `id`'s note; any Unicode, cut to 4000 characters.
     * Errors as [`DspiCore::snapshot_rename`].
     */
    @Throws(DspiException::class)
    fun snapshotSetNote(id: String, note: String): SnapshotInfo

    /**
     * Delete snapshot `id`. Errors as [`DspiCore::snapshot_rename`].
     */
    @Throws(DspiException::class)
    fun snapshotDelete(id: String)

    /**
     * Snapshot `id`'s document, to save as a file. Errors as
     * [`DspiCore::snapshot_rename`].
     */
    @Throws(DspiException::class)
    fun snapshotExport(id: String): String

    /**
     * File a snapshot document (`meta.kind = "snapshot"` with a `snapshot`
     * block, e.g. one exported from another console) in the store, under the
     * open device's serial (else the document's), named `name` ("" keeps the
     * document's) with `note`. A snapshot without an image is recalled
     * through the import's path.
     *
     * Errors: [`DspiError::InvalidArgument`] for text that is not a
     * document this build reads, or a document that is not a snapshot
     * ("not a snapshot — import it instead": a preset or template goes
     * through `config_import`); [`DspiError::Disconnected`] with no device
     * and no serial in the document; [`DspiError::Io`].
     */
    @Throws(DspiException::class)
    fun snapshotImport(text: String, name: String, note: String): SnapshotInfo

    /**
     * The snapshots of device `serial` ("" the open device) on both sides:
     * this console's store ([`DspiCore::snapshot_list`]) and, on a DSPi Link
     * session to a hub that keeps snapshots, the hub's
     * ([`DspiCore::hub_snapshots_list`]). Each row says where it is (`local`,
     * `hub` or `both`). **The hub's wins:** an id both sides hold with
     * different content (any field of the entry differs) is listed as the
     * hub's, and this console's as a local copy beside it; nothing is
     * overwritten. Never fails: a hub that cannot be read leaves the local
     * rows, with `hub_notice_key` saying why. A round trip on a hub: off the
     * UI thread.
     */
    fun snapshotListMerged(serial: String): SnapshotMergedList

    /**
     * The generator's capabilities: the `REQ_SIGGEN_GET_CAPS` header and
     * each signal type's descriptor.
     *
     * Ok with `supported = false` when the firmware has no generator (the
     * header stalls, is short, or has another layout version). `types`
     * always has [`SIGGEN_TYPE_COUNT`] entries of 4 parameters each; the
     * first `type_count` (the device's count, clamped to 15) are the
     * device's, and one whose descriptor could not be read has id `0xFF`
     * (the host then uses its own table for that type).
     *
     * Errors: [`DspiError::Disconnected`]; another transfer failure of the
     * header (a timeout) as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun siggenFetchCaps(): SiggenCaps

    /**
     * The config the generator runs (or last ran), as the device sanitised
     * it. `p` has 4 entries.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall
     * (no generator) or a short reply as [`DspiError::Transfer`];
     * [`DspiError::Unsupported`] for a config of another layout version.
     */
    @Throws(DspiException::class)
    fun siggenGetConfig(): SiggenConfig

    /**
     * Stage a config (a running generator restarts with it, fading). The
     * device validates type, mask and parameters; it does not play it until
     * [`SIGGEN_CTL_START`](crate::consts::SIGGEN_CTL_START).
     *
     * Current firmware stalls on a refused config; older firmware ACKs even
     * a refused one over USB, so read it back with
     * [`siggen_get_config`](Self::siggen_get_config) to be sure.
     *
     * Errors: [`DspiError::InvalidArgument`] unless `p` has exactly 4
     * entries (nothing is sent); [`DspiError::ReadOnly`] on a read-only
     * connection; [`DspiError::Refused`] (status 0) when the device stalls;
     * [`DspiError::Disconnected`] or [`DspiError::Transfer`] otherwise.
     */
    @Throws(DspiException::class)
    fun siggenSetConfig(config: SiggenConfig)

    /**
     * Run a control action: `SIGGEN_CTL_START` plays the staged config,
     * `SIGGEN_CTL_STOP` fades out, `SIGGEN_CTL_STOP_NOW` cuts at once
     * ([`consts`](crate::consts)).
     *
     * Errors: [`DspiError::InvalidArgument`] for an action above 0xFF (the
     * firmware reads only the low byte; nothing is sent);
     * [`DspiError::ReadOnly`] on a read-only connection;
     * [`DspiError::Refused`] when the device refuses (an unknown action, or
     * START without a valid config: status 0 for a stall, else the status
     * byte); [`DspiError::Disconnected`] or [`DspiError::Transfer`]
     * otherwise.
     */
    @Throws(DspiException::class)
    fun siggenControl(action: Int)

    /**
     * What the generator is doing now: state (`SIGGEN_STATE_*`: idle, fade
     * in, run, gap, fade out), elapsed ms, cycles done, the last stop
     * reason (`SIGGEN_STOP_*`), the walked output (0xFF when not walking)
     * and the current sweep frequency (Hz, 0 when not sweeping).
     *
     * Errors: as [`siggen_get_config`](Self::siggen_get_config).
     */
    @Throws(DspiException::class)
    fun siggenGetStatus(): SiggenStatus

    /**
     * One `REQ_GET_STATUS` `u32` counter or reading (`STAT_*` in
     * [`consts`](crate::consts)); units per constant. Sub-queries the
     * firmware does not know answer 0.
     *
     * Errors: [`DspiError::InvalidArgument`] for sub-query 9 (the meter
     * block, read by `fetch_status`) and for 64 and above (the debug-build
     * loop profiler, whose reads change state), nothing sent; [`DspiError::Disconnected`]; a transfer failure
     * or short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchStat(which: Int): Long

    /**
     * The output rings' health (Output Ring Health in the Stats window), or
     * `None` on firmware without `REQ_OUTPUT_LATENCY` or with a short reply to
     * it: show no section then. Seven transfers.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, or a stall or a
     * short reply on a counter, as [`DspiError::Transfer`]. A counter that
     * cannot be read fails the call rather than reading as 0.
     */
    @Throws(DspiException::class)
    fun fetchRingHealth(): RingHealth?

    /**
     * The live outputs' fill for the Stats rows: to frame resolution, on the
     * ring's own scale, with the band around the live latency target. Firmware
     * without `REQ_OUTPUT_LATENCY` keeps its fixed scale and fixed bands. Two
     * transfers. Use this rather than [`BufferStats`]' percentages, whose
     * 48-frame steps read as an empty ring at the lowest latency.
     *
     * Errors: as for [`DspiCore::fetch_buffer_stats`].
     */
    @Throws(DspiException::class)
    fun fetchOutputFills(): List<OutputFill>

    /**
     * The Stats window's fast poll: the buffer fill levels and the live
     * outputs' fill, as [`DspiCore::fetch_buffer_stats`] and
     * [`DspiCore::fetch_output_fills`] give them, from one transfer.
     *
     * The fill target is kept on the connection. It is read again, for one more
     * transfer on the tick after, when this core changed the latency, when a
     * notification says the settings moved (a preset, a bulk write, a format
     * change, a lost packet), and after a Link re-attach. The firmware does not
     * notify a latency change, so another client's reaches this through
     * [`DspiCore::fetch_ring_health`]: call that on the slow cadence alongside.
     * While a change has yet to apply the target is read each tick.
     *
     * Errors: as for [`DspiCore::fetch_buffer_stats`]. A failed read of the
     * target is not an error: `fills` is `None`.
     */
    @Throws(DspiException::class)
    fun fetchStatsTick(): StatsTick

    /**
     * The buffer fill levels (%) and their watermarks
     * (`REQ_GET_BUFFER_STATS`, 44 bytes). `spdif` has 4 entries; the first
     * `num_spdif` (at most 4) are live.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchBufferStats(): BufferStats

    /**
     * Start the buffer watermarks again from now
     * (`REQ_RESET_BUFFER_STATS`). Diagnostics housekeeping that changes no
     * setting and nothing in the bulk image, so like `clear_clips` it is
     * allowed on a read-only connection (PLAN §1.2). -- WP ROMODEF -- Not
     * in the client read-only mode: [`DspiError::ReadOnly`], nothing sent.
     *
     * Errors: [`DspiError::Refused`] for a status byte other than ACK (1);
     * [`DspiError::Disconnected`] or [`DspiError::Transfer`] otherwise.
     */
    @Throws(DspiException::class)
    fun resetBufferStats()

    /**
     * The S/PDIF receiver: lock state (0 inactive, 1 acquiring, 2 locked,
     * 3 relocking), input source, lock/loss counts, sample rate (Hz when
     * locked), parity errors, FIFO fill (%), and the receiver library's
     * debug state and callback counts (4 bits each).
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchSpdifRxStatus(): SpdifRxStatus

    /**
     * 24 bytes of IEC 60958 channel status of the locked S/PDIF input.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchSpdifRxChannelStatus(): List<Int>

    /**
     * GPIO of S/PDIF receiver `index` (0-3).
     *
     * Errors: [`DspiError::InvalidArgument`] for `index` 4 and above
     * (nothing sent); [`DspiError::Unsupported`] when the device has no
     * receiver `index` (it answers pin 0 for one it lacks; receiver 0
     * always exists, so its answer is passed on as is);
     * [`DspiError::Disconnected`]; a transfer failure as
     * [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchSpdifRxPin(index: Int): Int

    /**
     * The device's USB error counters (`REQ_GET_USB_ERROR_STATS`, 24
     * bytes): for the System Statistics window. A read, allowed on a
     * read-only connection. Current firmware answers zeros.
     *
     * Errors: [`DspiError::Disconnected`]; a transfer failure, a stall or a
     * short reply as [`DspiError::Transfer`].
     */
    @Throws(DspiException::class)
    fun fetchUsbErrorStats(): UsbErrorStats

    /**
     * The calibration flow as it stands, from memory: no traffic. It waits
     * for a poll or request in flight, so a slow link can hold it up as long
     * as that read: call it off the UI thread too.
     */
    fun coreVregCalView(): VregCalView

    /**
     * Read the device and advance the flow; never fails, the view says.
     * Call on every connect and about once a second while the page shows.
     * The only write that can go out is the next step of a run the user
     * started; never a `SET`, and none after the connection changed. Blocks
     * for a read: call it off the UI thread.
     */
    fun coreVregCalPoll(): VregCalView

    /**
     * Open the flow: the user reached it, from Advanced. Shows the warning
     * and what is on record; sends no write.
     *
     * `Disconnected`; `Unsupported` without a usable `EXT_CORE_VREG`;
     * `Denied` after a hub refused a write on this connection; `ReadOnly`;
     * `InvalidArgument` during a run.
     */
    @Throws(DspiException::class)
    fun coreVregCalOpen()

    /**
     * Close the flow: the user left. No traffic. `InvalidArgument` during a
     * run, which goes on until ended.
     */
    @Throws(DspiException::class)
    fun coreVregCalClose()

    /**
     * Start a run: the current record is cleared, `target` goes on trial
     * once the device shows that, and the soak counts for `soak_s` seconds.
     * `typed` is what the user typed when the view says this needs the word.
     *
     * `OvervoltWordRequired`, with no write, if it does and that is not
     * exactly the word. `InvalidArgument`, with no write, for a voltage
     * outside the build default to 1.25 V, a soak under the minimum, a trial
     * already running, or the wrong phase. `Disconnected`,
     * `Unsupported`, `ReadOnly`; `Refused`, `Denied`, `Locked`, `Transfer` for
     * the write, which is not retried.
     */
    @Throws(DspiException::class)
    fun coreVregCalStart(target: Int, soakS: Long, typed: String?)

    /**
     * Keep a trial found on the device: the soak counts from now, for
     * `soak_s` seconds. A trial outside the flow's range is left alone and
     * cannot pass. Sends nothing. Errors as for opening.
     */
    @Throws(DspiException::class)
    fun coreVregCalKeep(soakS: Long)

    /**
     * Save the voltage that passed, with a `SET`: the one explicit step from
     * a pass to flash. The status is read first, so a hang since the last
     * poll takes the pass back. Read back by later polls: `Committed` or
     * `VerifyFailed`. `typed` is the word when the view's `commit_needs_word`
     * says so, even if it was typed for the trial. A refusal leaves the flow in
     * `Passed`, with the trial running. Errors as for starting.
     *
     * Takes a confirmation token ([`crate::confirm`],
     * [`crate::ConfirmOp::VregSave`], WP P1TK; required since WP P1TZ):
     * without a good one, [`DspiError::ConfirmationRequired`] with no write,
     * noted in the view. The word stays as it is, beside the token. There is
     * no form without a token.
     */
    @Throws(DspiException::class)
    fun coreVregCalCommitConfirmed(typed: String?, token: String?)

    /**
     * End a trial, or abort a run, with `TRIAL_END`, at any time but while a
     * save is being read back. Works without a fresh status, so a run can be
     * aborted while reads are failing. `Disconnected` and `ReadOnly` change
     * nothing. A write that fails otherwise is not retried: later polls end
     * in `Ended`, or in `VerifyFailed`, from which it can be asked for again.
     */
    @Throws(DspiException::class)
    fun coreVregTrialEnd()

    /**
     * Manual `SET` from the Advanced page. `value` 0 is the reset to the
     * build default; anything else has the flow's limits and confirmation.
     * Read back by later polls, as a commit. Errors as for starting.
     *
     * Takes a confirmation token ([`crate::confirm`], WP P1TK; required since
     * WP P1TZ): [`DspiError::ConfirmationRequired`], with nothing sent,
     * without a good one. There is no form without a token.
     */
    @Throws(DspiException::class)
    fun coreVregManualSetConfirmed(value: Int, typed: String?, token: String?)

    /**
     * Manual `TRIAL`, with the flow's limits and confirmation. It shows as a
     * found trial on the next poll. Errors as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualTrial(value: Int, typed: String?)

    /**
     * Manual `AUTO`: the firmware's automatic raising after repeated hangs.
     * Errors as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualAuto(on: Boolean)

    /**
     * Manual `CLEAR`: forget the hang count and the last trial failure.
     * `InvalidArgument` during a run, whose result it would erase. Errors
     * otherwise as for starting.
     */
    @Throws(DspiException::class)
    fun coreVregManualClear()

    /**
     * Play an event on the demo device, for clients' tests and demo mode.
     * `seconds` is for [`VregDemoEvent::AdvanceUptime`]. `Unsupported`, with
     * no traffic, on anything but a simulated device.
     */
    @Throws(DspiException::class)
    fun coreVregDemoEvent(event: VregDemoEvent, seconds: Long)

    /**
     * Whether enabling output `output` would collide on Core 1, and if so
     * why, in the words [`DspiCore::write_param`] refuses it with: `None`
     * when it would not. The device decides
     * ([`DspiCore::check_core1_conflict`]); the words come from the layout.
     *
     * Errors: those of [`DspiCore::check_core1_conflict`].
     */
    @Throws(DspiException::class)
    fun core1ConflictReason(output: Int): String?

    /**
     * The database at `db_path`: for the "Update Database" dialog. Reads the file.
