     * Stateless (a free function in dspi-core); needs no device.
     */
    fun autoeqRebuildStart(dbPath: String, fetch: AutoEqFetch): AutoEqRebuild

    /**
     * A clip as a JSON document to keep: `{kind: "dspi.channelClip", version,
     * sourceChannel, sourceName, filters: [{filterType, bypass, freq, q, gain,
     * qp}], crossover: [...] | null, output: {gainDb, delayMs, muted} | null}`.
     *
     * Errors: [`DspiError::InvalidArgument`] for a clip of another version or
     * with a non-finite value (JSON has no NaN).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun channelClipToJson(clip: ChannelClip): String

    /**
     * A clip read back from its document ([`channel_clip_to_json`]).
     *
     * Errors: [`DspiError::InvalidArgument`] for text that is not a channel
     * clip (too long, not JSON, another `kind`, a missing or mistyped field)
     * and for a clip of another version, older or newer, named in the message.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun channelClipFromJson(text: String): ChannelClip

    /**
     * The combined level of `filters` at `freq` Hz, in dB.
     *
     * Bypassed and flat bands do not count; a crossover type counts with all
     * its sections; a type this build does not know counts as flat.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun computeResponse(filters: List<FilterParams>, freq: Float): Float

    /**
     * The combined level of `filters` in dB at each of the [`CURVE_POINTS`]
     * frequencies of [`curve_freq`]. Never below -300 dB.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun computeMagnitudeCurve(filters: List<FilterParams>): List<Double>

    /**
     * The combined phase of `filters` in degrees at each of the
     * [`CURVE_POINTS`] frequencies of [`curve_freq`]: within +-180, or, with
     * `unwrap`, continuous from the first point on.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun computePhaseCurve(filters: List<FilterParams>, unwrap: Boolean): List<Double>

    /**
     * The frequency of curve point `i` in Hz: 10 Hz at 0, 20 kHz at
     * `CURVE_POINTS - 1`, evenly spaced in log frequency. Larger `i` continue
     * the same spacing past 20 kHz.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun curveFreq(i: Long): Double

    /**
     * Whether the firmware accepts `map` as the crossfeed pair map on a device
     * with `num_pairs` stereo pairs: exactly [`crate::consts::CROSSFEED_MAP_PAIRS`]
     * bytes, and the rule of `dspi_proto::ext::PairMap::is_valid`.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun crossfeedPairMapValid(map: List<Int>, numPairs: Int): Boolean

    /**
     * The version facts of this build: crate version, the wire format versions
     * it writes and reads, the bulk image size and the curve size.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun coreInfo(): CoreInfo

    /**
     * A gain in dB on the device's 0.1 dB grid, as the gain setters send it.
     *
     * Halves round away from zero and -0 becomes +0. No clamping: NaN and the
     * infinities come back unchanged, and so does a value too large to scale.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun quantizeGain(db: Float): Float

    /**
     * A delay in ms on a 0.0001 ms grid, as the delay setters send it.
     *
     * Halves round away from zero and -0 becomes +0. No clamping (callers bound
     * the delay to its range afterwards); NaN and the infinities pass through.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun quantizeDelay(ms: Float): Float

    /**
     * A master volume in dB as [`crate::DspiCore::set_master_volume`] keeps
     * it: -128 (mute) at or below -128, else on a 0.5 dB grid (halves away
     * from zero) within -127..=0. -0 becomes +0. NaN comes back as NaN (the
     * setter refuses it).
     *
     * A slider shows this value while the user drags, so it shows what the
     * device gets.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun quantizeMasterVolume(db: Float): Float

    /**
     * The biquad sections the curves of `filters` are computed from, in
     * cascade order: what a GPU renderer evaluates per pixel to draw the same
     * curve as [`compute_magnitude_curve`].
     *
     * A bypassed or flat band adds none; a crossover type adds each of its
     * sections as the firmware builds them; a type this build does not know,
     * or a band whose values give a non-finite coefficient, adds a unity
     * section. Call it with one band for that band's own sections.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun curveSections(filters: List<FilterParams>): List<BiquadSection>

    /**
     * Every name [`DspiCore::feature_present`] knows: the connect probe's, then
     * [`DERIVED_FEATURES`]. A client gates each section by one of these, never
     * by a wire format or firmware version.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun knownFeatureNames(): List<String>

    /**
     * Check a `.dspipreset` document and describe it, as JSON
     * `{ok, error, name, platform, firmware, savedUtc}`. `ok` is false, with the
     * reason in `error`, for text that is not a document this build reads: not
     * JSON, no schema version or a newer one, no channels, or over
     * [`MAX_FILE_BYTES`]. Needs no device.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun configInspect(text: String): String

    /**
     * What differs between two `.dspipreset` documents, `before` and `after`,
     * with no device (PRO1 W5). `after` is read on top of `before`, as an
     * import of it after the other would be, so a value `after` holds none for
     * is no change; both are read onto a device shaped as `before`'s `meta`
     * says.
     *
     * Returns JSON `{ok, error, rows, count, blocks, summary, notes, kind}`:
     * `rows` one per changed value, `{block, section, item, before, after}`,
     * `block` the import block that carries it (`eq`, `crossover`, `routing`,
     * `outputs`, `limiters`, `effects`, `volumes`, `hardware`, `names`);
     * `blocks` the number of rows per block; `summary` the unsaved-changes
     * list's sentences for the same change; `notes` what reading `after`
     * reported (channels missing, values left alone or clamped); `kind`
     * `after`'s `meta.kind`. `{ok: false, error}` when either text is not a
     * document this build reads (the error names which).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun configDiff(before: String, after: String): String

    /**
     * Check a UF2 image: block structure, magic numbers, family id, the flash
     * range it covers, and the DSPi version string inside it. Never panics; a
     * refused image comes back with `valid == false` and the reason in
     * `problem` (fit for "This is not a firmware file: <problem>").
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun uf2Inspect(image: List<Int>): Uf2Info

    /**
     * Boards in BOOTSEL mode on the bus (USB `2E8A:0003` RP2040, `2E8A:000F`
     * RP2350). 0/0 where the bus cannot be enumerated (Android, and a build
     * without the `usb` feature: iOS).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun bootloaderCounts(): BootloaderCounts

    /**
     * Mounted bootloader drives (`INFO_UF2.TXT` at the root naming an RP2040 or
     * RP2350 boot ROM): Linux `/proc/self/mountinfo` + `/run/media`, macOS
     * `/Volumes`, Windows removable drives labelled `RPI-RP2` / `RP2350`.
     * Empty on Android.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun bootloaderDrives(): List<BootloaderDrive>

    /**
     * The record for a board already in the bootloader: unknown, so the check
     * asks.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun firmwareGuardBoardInBootloader(): FirmwareGuardBoard

    /**
     * The guard (module docs). `typed_confirmation` is what the user typed, ""
     * if nothing yet; call again with it when the decision is
     * `NeedsConfirmation`. Pure and cheap enough for a UI thread's button, but
     * it does parse the whole image. Never panics.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun firmwareGuardCheck(image: List<Int>, board: FirmwareGuardBoard, typedConfirmation: String): FirmwareGuardVerdict

    /**
     * Whether `image` is the bundled file `name` (a file name; a leading path
