     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun linkParseAddress(text: String): LinkAddress

    /**
     * The WebSocket URL for a hub. An empty `path` is the default (`/dspi/v1`).
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    fun linkWsUrl(host: String, port: Int, path: String): String

    /**
     * `GET /dspi/v1/info` (spec 3.2). Blocks up to a few seconds.
     *
     * Errors: [`DspiError::Link`] with `io` or `protocol`.
     *
     * Stateless (a free function in dspi-core); needs no device.
     */
    @Throws(DspiException::class)
    fun linkFetchInfo(host: String, port: Int): LinkInfo

